from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///database.db'
db = SQLAlchemy(app)

class Borrower(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80))
    email = db.Column(db.String(120))
    location = db.Column(db.String(80))
    loans = db.relationship('Loan', backref='borrower', lazy=True)

@app.route('/borrower/<int:borrower_id>', methods=['GET'])
def get_borrower(borrower_id):
    query = f"SELECT * FROM borrowers WHERE id = {borrower_id}"

    borrower = db.session.execute(query).fetchone()

    if borrower:
        return jsonify({
            'id': borrower.id,
            'name': borrower.name,
            'email': borrower.email,
            'location': borrower.location
        })
    else:
        return jsonify({'error': 'Borrower not found'}), 404

if __name__ == '__main__':
    app.run()

